package com.jobradar.taxonomy.skill;import com.jobradar.common.api.*;import com.jobradar.common.pagination.PaginationParameters;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController public class SkillController{private final SkillService s;public SkillController(SkillService s){this.s=s;}@GetMapping("/api/v1/skills")public ApiResponse<PaginatedResponse<SkillDto>> list(@RequestParam(required=false)String search,@Valid @ModelAttribute PaginationParameters p){return ApiResponse.success("Skills retrieved successfully",s.browse(search,p,false,false));}@GetMapping("/api/v1/skills/popular")public ApiResponse<PaginatedResponse<SkillDto>> popular(@RequestParam(required=false)String search,@Valid @ModelAttribute PaginationParameters p){return ApiResponse.success("Popular skills retrieved successfully",s.browse(search,p,true,false));}@GetMapping("/api/v1/admin/skills")public ApiResponse<PaginatedResponse<SkillDto>> adminList(@RequestParam(required=false)String search,@Valid @ModelAttribute PaginationParameters p){return ApiResponse.success("Skills retrieved successfully",s.browse(search,p,false,true));}@PostMapping("/api/v1/admin/skills")@ResponseStatus(HttpStatus.CREATED)public ApiResponse<SkillDto> create(@Valid @RequestBody SkillRequest r){return ApiResponse.success("Skill created successfully",s.create(r));}@PutMapping("/api/v1/admin/skills/{id}")public ApiResponse<SkillDto> update(@PathVariable Integer id,@Valid @RequestBody SkillRequest r){return ApiResponse.success("Skill updated successfully",s.update(id,r));}@PatchMapping("/api/v1/admin/skills/{id}/{state:activate|deactivate}")public ApiResponse<Void> active(@PathVariable Integer id,@PathVariable String state){s.active(id,state.equals("activate"));return ApiResponse.success("Skill status updated successfully",null);}}
